        <div class="row g-3">
            <div class="col-12"><label class="form-label">Approved User Role *</label><select class="form-select" name="role_assignment_id" id="scope-role-assignment" required><option value="">Select</option><?php foreach ($roleAssignments as $assignment): ?><option value="<?= e($assignment['id']) ?>" data-role-id="<?= e($assignment['role_id']) ?>" data-level="<?= e($assignment['role_level']) ?>"><?= e($assignment['username'] . ' - ' . $assignment['role_name']) ?></option><?php endforeach; ?></select></div>
