            <div class="col-12" id="scope-location-wrap"><label class="form-label" for="scope-location-search">Office or Location</label><input class="form-control form-control-sm mb-1" type="search" id="scope-location-search" placeholder="Search by DAD number, name, or official code" autocomplete="off"><select class="form-select" name="location_id" id="scope-location"><option value="">Select a user role first</option></select><div class="form-text">Select the office or location for this role.</div></div>
