    </div>
    <div class="modal-footer"><button class="btn btn-primary">Submit</button></div>
</form></div></div>
<script nonce="<?= e(SecurityHeaders::nonce()) ?>">(()=>{const assignment=document.getElementById('scope-role-assignment'),location=document.getElementById('scope-location'),search=document.getElementById('scope-location-search'),wrap=document.getElementById('scope-location-wrap'),rule=document.getElementById('scope-rule');if(!assignment||!location||!search||!wrap||!rule)return;const endpoint=<?= json_encode(url('access-management/assignment-locations'),JSON_THROW_ON_ERROR) ?>,types={DISTRICT:'District',ASC:'Agrarian Service Center',ARPA:'ARPA Division'},modes={DISTRICT:'Includes offices under this District',ASC:'Access for this office',ARPA:'Access for this ARPA Division'};let timer=0,request=null;const clear=(label)=>location.replaceChildren(new Option(label,''));const load=async()=>{const option=assignment.selectedOptions[0],level=option?.dataset.level||'',roleId=option?.dataset.roleId||'',type=types[level]||'';rule.value=type?type+' - '+modes[level]:'National Level';wrap.hidden=type==='';location.required=type!=='';if(type===''||!roleId){clear('National Level');return;}request?.abort();request=new AbortController();clear('Loading locations...');try{const query=new URLSearchParams({role_id:roleId,q:search.value.trim(),limit:'100'}),response=await fetch(endpoint+'?'+query,{headers:{Accept:'application/json'},signal:request.signal});if(!response.ok)throw new Error('Location lookup denied');const data=await response.json();clear(data.results.length?'Select location':'No matching locations');for(const row of data.results)location.add(new Option([row.location_type,row.dad_number,row.name_en].filter(Boolean).join(' | '),row.id));}catch(error){if(error.name!=='AbortError')clear('Unable to load locations');}};assignment.addEventListener('change',()=>{search.value='';load();});search.addEventListener('input',()=>{clearTimeout(timer);timer=setTimeout(load,250);});load();})();</script>
